import{_ as a,C as o,o as n,c as r,E as i,a2 as s}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse('{"title":"权限上下文必须由宿主生成","description":"","frontmatter":{"title":"权限上下文必须由宿主生成","date":"2026-08-27","column":"industry-architecture","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"智能体平台应如何把账户权限证据传给工具，同时避免请求方伪造、扩大或继续使用过期权限？","summary":"OpenAI Codex（代码智能体）的一项已合并变更展示了有界的权限证据代理模式：宿主移除调用方副本，核验当前账户，只在全部能力条件成立时注入上下文，无法核验则收缩为无授权状态。","sources":["research/analysis/Q-20260827-02-host-minted-capability-scoped-access-evidence.md"],"item_id":"Q-20260827-02","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-27-authority-context-must-be-host-minted-cover-v2.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/industry/2026-08-27-authority-context-must-be-host-minted.md","filePath":"zh/industry/2026-08-27-authority-context-must-be-host-minted.md","lastUpdated":1788162175000}'),c={name:"zh/industry/2026-08-27-authority-context-must-be-host-minted.md"};function d(p,e,l,u,h,m){const t=o("ArticleCover");return n(),r("div",null,[i(t,{image:"/assets/covers/daily-2026-08-27-authority-context-must-be-host-minted-cover-v2.png",kicker:"行业架构 · 每日研究",title:"权限上下文必须由宿主生成",summary:"OpenAI Codex（代码智能体）的一项已合并变更展示了有界的权限证据代理模式：宿主移除调用方副本，核验当前账户，只在全部能力条件成立时注入上下文，无法核验则收缩为无授权状态。",version:"Q-20260827-02",status:"Daily Runtime V5 · 2026-08-27",languageHref:"/en/industry/2026-08-27-authority-context-must-be-host-minted",languageLabel:"English"}),e[0]||(e[0]=s('<h1 id="权限上下文必须由宿主生成" tabindex="-1">权限上下文必须由宿主生成 <a class="header-anchor" href="#权限上下文必须由宿主生成" aria-label="Permalink to &quot;权限上下文必须由宿主生成&quot;">​</a></h1><p>如果一个工具调用可以自己附带“我拥有某项权限”的元数据，而平台又把这段元数据当作授权依据，请求方就同时成为了证据的声明者和受益者。无论字段名称多正式，这仍然是一条循环授权路径。</p><p>OpenAI Codex（代码智能体）的一项已合并维护者变更提供了一个可检查的反例。针对特定的本地插件调用，宿主不会信任调用方附带的权限字段，而是先移除它，再依据当前对话服务账户身份查询访问状态。只有多个条件同时成立时，核验结果才会进入工具调用；无法核验、账户切换或返回数据异常都会收缩为“未知”和空授权集合。</p><p>由此得到的核心判断是：<strong>携带权限的访问上下文，应由能够核验支配身份的宿主生成，应替换而不是信任调用方副本，并且只能跨越显式合格的能力边界；无法核验时必须降级为无授权状态。至于下游是否正确执行，仍是另一项独立责任。</strong></p><h2 id="请求者不能同时签发自己的权限证据" tabindex="-1">请求者不能同时签发自己的权限证据 <a class="header-anchor" href="#请求者不能同时签发自己的权限证据" aria-label="Permalink to &quot;请求者不能同时签发自己的权限证据&quot;">​</a></h2><p>身份信息与权限证据常被当作普通请求元数据传递，但二者的信任方向完全不同。普通参数描述调用方想做什么；权限证据说明平台为什么允许它这样做。后一种信息如果来自调用方，就没有独立于请求本身的权威来源。</p><p>所选实现先删除调用方提供的同名字段，再由宿主生成 verified 或 unknown 结果。这一步并不复杂，却确立了关键边界：请求能力可以表达需求，不能铸造证明自身有权执行该需求的证据。</p><p>宿主之所以适合承担这一职责，不只是因为它“更可信”，而是因为它能访问当前认证通道、账户标识和平台策略。权限上下文因此不应是一个可以从上游随意透传的字典，而应是带有签发者、身份版本、核验时间和作用范围的派生事实。</p><h2 id="能力范围应是一组同时成立的条件" tabindex="-1">能力范围应是一组同时成立的条件 <a class="header-anchor" href="#能力范围应是一组同时成立的条件" aria-label="Permalink to &quot;能力范围应是一组同时成立的条件&quot;">​</a></h2><p>这项变更没有用一个宽泛开关决定是否注入。公开实现要求以下条件共同成立：工具显式请求指定访问资格；服务器属于已安装或已选择的插件；运行环境为本地默认环境；来源为标准输入输出；工具声明为只读；参数不存在或为空对象。</p><p>这些条件分别回答不同问题：谁提供能力、通过什么边界调用、动作是否会修改状态、请求形态是否仍在已审查范围内。只要其中一项变化，原有证据就不应自动扩大到新场景。</p><p>这类合取门槛有时会带来功能上的假阴性，例如合法的远程工具、带参数读取或写操作可能无法获得相同上下文。但正确做法不是静默放宽现有条件，而是为新场景建立新的合同：说明额外风险、权威来源、参数约束、审计记录和失败语义。权限范围是授权证据的一部分，不是注入完成后的附加过滤器。</p><h2 id="身份连续性与失败语义决定证据是否仍然有效" tabindex="-1">身份连续性与失败语义决定证据是否仍然有效 <a class="header-anchor" href="#身份连续性与失败语义决定证据是否仍然有效" aria-label="Permalink to &quot;身份连续性与失败语义决定证据是否仍然有效&quot;">​</a></h2><p>长时间运行的会话中，用户可能切换账户，组织策略也可能变化。只在会话创建时读取一次账户状态，会让后来执行的工具调用继续携带陈旧证据。</p><p>公开代码把查询限制在 2.5 秒内，禁止重定向，限制响应体为 1 MiB（兆二进制字节），并在请求前后检查账户身份是否一致。不支持的认证、请求失败、超时、数据异常、状态不一致或账户切换都会得到宿主生成的 unknown 与空授权，而不会回退到调用方提供的积极声明。</p><p>这里的安全价值依赖两个方向同时闭合。生产端必须在不确定时收缩；消费端也必须把 unknown 和空授权解释为“不可授权”。如果下游把 unknown 当成“没有限制”，或退回另一个未经核验的来源，上游的失败关闭就会失效。</p><h2 id="更好的来源不等于完整授权" tabindex="-1">更好的来源不等于完整授权 <a class="header-anchor" href="#更好的来源不等于完整授权" aria-label="Permalink to &quot;更好的来源不等于完整授权&quot;">​</a></h2><p>这项机制能够支持的结论很明确：在一个特定的代码智能体本地插件协议路径上，权限上下文由宿主产生，调用方副本会被剥离，注入受多项条件限制，核验失败会收缩权限。实现和测试比单纯的产品声明提供了更强的机制证据。</p><p>但它不能证明每个下游插件都会正确执行这些字段，不能证明服务端策略本身正确，也不能把这段元数据升级成凭证、能力令牌或密码学证明。它展示的是狭窄的“权限证据代理”，不是完整授权系统。</p><p>审计一个类似设计时，至少应能回答四个问题：谁签发了上下文？哪些条件让本次调用具备接收资格？核验绑定了哪个身份版本和时间窗口？接收端如何解释 verified、unknown 与空授权？只有这四类记录能够连成一条可复核证据链，权限元数据才不会重新退化成未经验证的自我声明。</p><p><strong>一手证据：</strong> <a href="https://github.com/openai/codex/commit/ae357e7250402af7c3bbede18a46cc565a7670d4" target="_blank" rel="noreferrer">OpenAI Codex 已合并提交 ae357e72</a>。该实现与维护者测试支持本文所述的宿主签发、能力收缩和失败关闭机制，不构成端到端授权正确性的独立验证。</p>',21))])}const y=a(c,[["render",d]]);export{b as __pageData,y as default};
